package com.mfg.common.service;
import com.mfg.common.api.*;import com.mfg.common.exception.BizException;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor public class P3CrudService{private final JdbcTemplate db;private final List<DataVisibility> visibility;
 private static final Map<String,String>T=Map.ofEntries(Map.entry("onboarding","src_srm.srm_onboarding"),Map.entry("rfqs","src_srm.srm_rfq"),Map.entry("quotes","src_srm.srm_supplier_quote"),Map.entry("purchase-orders","src_srm.srm_purchase_order"),Map.entry("asns","src_srm.srm_asn"),Map.entry("supplier-quality","src_srm.srm_supplier_quality"),Map.entry("performance","src_srm.srm_supplier_performance"),Map.entry("receipts","src_wms.wms_receipt"),Map.entry("putaway","src_wms.wms_putaway"),Map.entry("inventories","src_wms.wms_inventory"),Map.entry("inventory-actions","src_wms.wms_inventory_action"),Map.entry("transfers","src_wms.wms_transfer"),Map.entry("counts","src_wms.wms_count_plan"),Map.entry("standards","src_qms.qms_standard"),Map.entry("sampling-plans","src_qms.qms_sampling_plan"),Map.entry("inspections","src_qms.qms_inspection"),Map.entry("ncrs","src_qms.qms_ncr"),Map.entry("reworks","src_qms.qms_rework"),Map.entry("capas","src_qms.qms_capa"),Map.entry("8d","src_qms.qms_eight_d"));
 private String t(String k){String v=T.get(k);if(v==null)throw BizException.of(ErrorCode.PARAM_INVALID,"不支持的业务对象");return v;}private String sc(String k){return switch(k){case"purchase-orders"->"order_status";case"inspections"->"inspect_result";case"reworks"->"rework_status";case"supplier-quality"->"eight_d_status";case"performance","inventories","quotes"->null;default->"status";};}
 public Page<Map<String,Object>>page(String k,String q,String st,int page,int size){String tb=t(k),kw=q==null?"":q,scol=sc(k),where=" WHERE (?='' OR CAST(id AS CHAR) LIKE ? OR CONCAT_WS(' ',"+cols(k)+") LIKE ?)"+(scol==null?"":" AND (?='' OR "+scol+"=?)");List<Object>a=new ArrayList<>(List.of(kw,"%"+kw+"%","%"+kw+"%"));if(scol!=null){String x=st==null?"":st;a.add(x);a.add(x);}for(DataVisibility v:visibility){var filter=v.filter(tb,"");where+=" AND ("+filter.sql()+")";a.addAll(filter.parameters());}Long n=db.queryForObject("SELECT COUNT(*) FROM "+tb+where,Long.class,a.toArray());int p=Math.max(0,page-1),z=Math.min(200,Math.max(1,size));a.add(z);a.add(p*z);return new PageImpl<>(db.queryForList("SELECT * FROM "+tb+where+" ORDER BY id DESC LIMIT ? OFFSET ?",a.toArray()),PageRequest.of(p,z),n==null?0:n);}
 public Map<String,Object>detail(String k,long id){String table=t(k),where=" WHERE id=?";List<Object> args=new ArrayList<>();args.add(id);for(DataVisibility v:visibility){var f=v.filter(table,"");where+=" AND ("+f.sql()+")";args.addAll(f.parameters());}var rows=db.queryForList("SELECT * FROM "+table+where,args.toArray());if(rows.isEmpty())throw BizException.of(ErrorCode.DATA_SCOPE_DENIED,"记录不存在或超出数据范围");return rows.get(0);}
 @Transactional public Map<String,Object>create(String k,Map<String,Object>x){String tb=t(k);String[]p=tb.split("\\.");Set<String>allowed=new HashSet<>(db.queryForList("SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=? AND TABLE_NAME=? AND EXTRA NOT LIKE '%auto_increment%'",String.class,p[0],p[1]));Map<String,Object>v=new LinkedHashMap<>();x.forEach((a,b)->{String c=a.replaceAll("([a-z])([A-Z])","$1_$2").toLowerCase();if(allowed.contains(c))v.put(c,b);});if(v.isEmpty())throw BizException.of(ErrorCode.PARAM_INVALID,"没有可保存字段");db.update("INSERT INTO "+tb+"("+String.join(",",v.keySet())+") VALUES("+String.join(",",Collections.nCopies(v.size(),"?"))+")",v.values().toArray());return detail(k,Objects.requireNonNull(db.queryForObject("SELECT LAST_INSERT_ID()",Long.class)));}
 @Transactional public Map<String,Object>status(String k,long id,String value){String c=sc(k);if(c==null)throw BizException.of(ErrorCode.PARAM_INVALID,"对象没有状态字段");Map<String,Object>r=detail(k,id);String current=String.valueOf(r.get(c));if(current.equals(value))return r;Map<String,Set<String>>rules=rules(k);if(!rules.getOrDefault(current,Set.of()).contains(value))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"不允许从"+current+"变更为"+value);if(db.update("UPDATE "+t(k)+" SET "+c+"=? WHERE id=?",value,id)==0)throw BizException.notFound("业务记录",id);return detail(k,id);}
 private Map<String,Set<String>>rules(String k){return switch(k){case"onboarding"->Map.of("DRAFT",Set.of("APPROVING"),"APPROVING",Set.of("APPROVED","REJECTED"),"APPROVED",Set.of("CERTIFIED","BLACKLISTED"),"CERTIFIED",Set.of("BLACKLISTED"));case"rfqs"->Map.of("DRAFT",Set.of("PUBLISHED","CANCELLED"),"PUBLISHED",Set.of("QUOTING","CLOSED","CANCELLED"),"QUOTING",Set.of("CLOSED","CANCELLED"),"CLOSED",Set.of("AWARDED","CANCELLED"));case"asns"->Map.of("DRAFT",Set.of("SHIPPED","CANCELLED"),"SHIPPED",Set.of("ARRIVED","CANCELLED"),"ARRIVED",Set.of("RECEIVED","RETURNED"));case"putaway"->Map.of("CREATED",Set.of("PROCESSING","CANCELLED"),"PROCESSING",Set.of("COMPLETED","CANCELLED"));case"transfers"->Map.of("DRAFT",Set.of("CONFIRMED","CANCELLED"),"CONFIRMED",Set.of("COMPLETED","CANCELLED"));case"counts"->Map.of("DRAFT",Set.of("RELEASED","CANCELLED"),"RELEASED",Set.of("COUNTING"),"COUNTING",Set.of("REVIEWING"),"REVIEWING",Set.of("COMPLETED"));case"ncrs"->Map.of("OPEN",Set.of("REVIEWING"),"REVIEWING",Set.of("REWORK","SCRAPPED","CONCESSION","RETURNED"),"REWORK",Set.of("CLOSED"),"SCRAPPED",Set.of("CLOSED"),"CONCESSION",Set.of("CLOSED"),"RETURNED",Set.of("CLOSED"));case"capas"->Map.of("DRAFT",Set.of("IMPLEMENTING"),"IMPLEMENTING",Set.of("VERIFYING"),"VERIFYING",Set.of("CLOSED","IMPLEMENTING"));case"8d"->Map.of("OPEN",Set.of("SUBMITTED"),"SUBMITTED",Set.of("VERIFYING"),"VERIFYING",Set.of("CLOSED","SUBMITTED"));default->Map.of();};}
 private String cols(String k){return switch(k){case"onboarding"->"application_no,supplier_name";case"rfqs"->"rfq_no,title,material_code";case"purchase-orders"->"purchase_order_no,supplier_code,material_code";case"asns"->"asn_no,purchase_order_no,supplier_code";case"supplier-quality"->"issue_no,supplier_code,source_no";case"performance"->"supplier_code,period_code";case"receipts"->"receipt_no,asn_no,material_code";case"putaway"->"putaway_no,receipt_no,material_code";case"inventories"->"material_code,warehouse_code,location_code,batch_no";case"inventory-actions"->"action_no,material_code,source_no";case"transfers"->"transfer_no,material_code";case"counts"->"count_no,warehouse_code";case"standards"->"standard_code,standard_name,material_code";case"sampling-plans"->"plan_code,plan_name";case"inspections"->"inspection_no,material_code,source_no";case"ncrs"->"ncr_no,inspection_no,material_code";case"reworks"->"rework_no,defect_no,material_code";case"capas"->"capa_no,ncr_no,owner_user";case"8d"->"eight_d_no,ncr_no,supplier_code";default->"id";};}}
